public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box must not be null");
    }

    double width = box.getWidth();
    Point2D.Double midpoint = new Point2D.Double(box.getX() + width / 2, box.getY());
    Area upperArea = new Area(box);
    upperArea.subtract(new Area(new Rectangle2D.Double(box.getX(), box.getY(), midpoint.getX() - box.getX(), box.getHeight())));

    Area lowerArea = new Area(box);
    lowerArea.subtract(new Area(new Rectangle2D.Double(midpoint.getX() - box.getWidth() / 2, box.getY(), box.getWidth() / 2 + box.getX(), box.getHeight())));

    return Pair.with(upperArea.toShape(), lowerArea.toShape());
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double width = box.getWidth();
    double halfWidth = width / 2.0;
    return new Pair<>(new Box2D(box.getLowerLeft(), new Point2D.Double(halfWidth, box.getLowerLeft().getY())), new Box2D(new Point2D.Double(halfWidth, box.getUpperLeft().getY()), box.getUpperRight()));
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double x = box.getX();
    double w = box.getWidth();
    Box2D left = new Box2D(x, 0, 0, w / 2);
    Box2D right = new Box2D(x + w / 2, 0, w / 2, w);
    return Pair.create(left, right);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    Point2D midPoint = new Point2D.Double(box.getX() + box.getWidth()/2.0, box.getY());
    Box2D leftBox = new Rectangle2D.Double(box.getX(), box.getY(), midPoint.getX() - box.getX(), box.getHeight());
    Box2D rightBox = new Rectangle2D.Double(midPoint.getX(), box.getY(), box.getX() + box.getWidth() - midPoint.getX(), box.getHeight());
    return new ImmutablePair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
  double width = box.getWidth();
  Rectangle2D lowerHalf = box.createChild(new Rectangle2D.Double(box.getMinX(), box.getMinY(), width / 2, box.getHeight()));
  Rectangle2D upperHalf = box.createChild(new Rectangle2D.Double(box.getMinX() + width / 2, box.getMinY(), width / 2, box.getHeight()));
  return new Pair<>(lowerHalf, upperHalf);
}

