public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertices = new ArrayList<>();
    for (E edge : tour) {
        V v = graph.getEdgeSource(edge);
        V w = graph.getEdgeTarget(edge);
        // Ensure the vertices are added in the order they appear
        if (!vertices.contains(v) || !vertices.contains(w)) {
            vertices.add(v);
            vertices.add(w);
        }
    }
    GraphPath<V,E> path = new GraphPath<>(graph, vertices, null);
    return path;
}

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<Edge> edges = new ArrayList<>(tour.size());
    for (E edge : tour) {
        edges.add(graph.get(edge));
    }
    return new GraphPath<>(graph, edges);
}

protected static GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        List<Vertex<V>> path = new ArrayList<>();
        Vertex<V> current = graph.getVertices().iterator().next();
        path.add(current);

        Set<E> visited = new HashSet<>(tour);
        while (visited.size() < graph.getVertices().size()) {
            Set<E> outgoingEdges = current.getOutgoingEdges();
            if (outgoingEdges.stream().noneMatch(visited::contains)) {
                E nextEdge = outgoingEdges.iterator().next();
                Vertex<V> nextVertex = graph.getEdgeTarget(nextEdge);
                path.add(nextVertex);
                visited.add(nextEdge);
                current = nextVertex;
            } else {
                while (!visited.contains(current.getOutgoingEdges().stream().iterator().next())) {
                    path.remove(path.size() - 1);
                    current = path.get(path.size() - 1);
                }
            }
        }

        GraphPath<V, E> graphPath = new GraphPath<>();
        graphPath.setNodes(path);
        graphPath.setEdges(path.stream().map(Vertex::getEdge).collect(Collectors.toList()));
        return graphPath;
    }

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    GraphPath<V> path = new GraphPath<V>();
    for (E edge : tour) {
        V sourceNode = graph.getSource(edge);
        V targetNode = graph.getTarget(edge);
        path.addSegment(sourceNode, targetNode);
    }
    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>();
    Stack<Node<V, E>> nodes = new Stack<>();
    Node<V, E> current = graph.getInitialNode();

    for (E edge : tour) {
        path.addNode(current);
        nodes.push(current);
        current = graph.getFinalNode(edge);
    }

    while (!nodes.isEmpty()) {
        path.addEdge(nodes.pop().getKey(), nodes.peek().getKey());
    }

    return path;
}

