        // Calculate the suffix sum list
        for (int i = bounds.size() - 1; i >= 0; i--) {
            suffixSumList.add(totalSum);
            totalSum += bounds.get(i);
        }

        // Reverse the list to get the correct order
        Collections.reverse(suffixSumList);

        return Pair.of(suffixSumList, totalSum);
    }

