public static String base64Decode(String s){
    int len = s.length();
    if (len & 0x01 != 0) {
        throw new IllegalArgumentException("InvalidBase64");
    }
    byte[] decoded = new byte[len >> 1];
    for (int i = 0; i < len; i += 2) {
        int idx1 = base64().decode(s.charAt(i));
        int idx2 = base64().decode(s.charAt(i + 1));
        decoded[i >> 1] = (byte)(((idx1 << 4) | idx2) & 0xff);
    }
    return new String(decoded);
}

